<?php $module='orders';$title=$order['order_number'];$description='Order details and fulfillment history.';require __DIR__.'/header.php'; ?>
<div class="order-grid"><section class="panel"><div class="panel-heading"><div><h2>Order items</h2><p>Prices, quantities and customer address are the original order snapshots.</p></div><span class="pill"><?= $e($order['status']) ?></span></div><div class="table-scroll"><table class="admin-table"><thead><tr><th>Material / SKU</th><th>Quantity</th><th>Total</th></tr></thead><tbody><?php foreach($order['items'] as $item): ?><tr><td><strong><?= $e($item['name']) ?></strong><small><?= $e($item['sku']) ?></small></td><td><?= $q($item['qty_milli']) ?> <?= $e($item['sell_unit']) ?></td><td><?= $m($item['line_total_minor']) ?></td></tr><?php endforeach; ?></tbody></table></div><dl class="totals"><?php foreach(['subtotal_minor'=>'Subtotal','discount_minor'=>'Discount','shipping_minor'=>'Shipping','tax_minor'=>'Tax','total_minor'=>'Order total'] as $fieldName=>$label): ?><div><dt><?= $label ?></dt><dd><?= $m($order[$fieldName]) ?></dd></div><?php endforeach; ?></dl><p class="help-text">Payment: <?= $e($order['payment_mode']) ?> · <?= $e($order['payment_status']) ?></p>
<?php $due=(int)($order['amount_due_minor']??$order['total_minor']);$balance=(int)$order['total_minor']-$due; ?>
<?php if($balance>0): ?><dl class="totals"><div><dt>Advance collected online</dt><dd><?= $m($due) ?></dd></div><div><dt>Balance due on delivery</dt><dd><?= $m($balance) ?></dd></div></dl>
<?php if($order['payment_status']==='advance_paid'&&$can('admin.orders.edit')): ?><form method="post" action="<?= $u('admin/order/balance') ?>" data-confirm="Record the remaining balance as collected (cash on delivery)?"><?php $hidden(['csrf'=>$csrf,'id'=>$order['id'],'revision'=>$order['revision'],'operation_key'=>$key()]); ?><button class="button">Record balance collected</button></form><?php endif; ?><?php endif; ?></section>
<?php if($order['status']==='awaiting_verification'): ?><section class="panel"><div class="panel-heading"><div><h2>Verify this order</h2><p>Call the customer to confirm the order before it is accepted.</p></div><span class="pill">Attempts: <?= (int)($order['verify_attempts']??0) ?></span></div>
<p class="help-text">Call <strong><?= $e($order['address']['phone']??'—') ?></strong> (<?= $e($order['address']['recipient']??'') ?>).<?php if(!empty($order['verify_deadline_at'])): ?> Auto-confirms at <?= gmdate('Y-m-d H:i',(int)$order['verify_deadline_at']) ?> UTC if not actioned.<?php endif; ?></p>
<?php if(!empty($order['verify_outcome'])): ?><p class="help-text">Last outcome: <strong><?= $e($order['verify_outcome']) ?></strong><?= !empty($order['verify_note'])?' — '.$e($order['verify_note']):'' ?></p><?php endif; ?>
<?php if($can('admin.orders.edit')): ?><form method="post" action="<?= $u('admin/order/verify') ?>"><?php $hidden(['csrf'=>$csrf,'id'=>$order['id'],'revision'=>$order['revision'],'operation_key'=>$key()]); ?>
<label class="field full"><span>Call note (optional)</span><input type="text" name="note" maxlength="500" value="<?= $e($values['note']??'') ?>"></label>
<div class="form-actions"><button class="button" name="outcome" value="reached">Confirm order</button><button class="button secondary" name="outcome" value="unreachable" formnovalidate>Log failed attempt</button><button class="button danger" name="outcome" value="rejected" data-confirm="Reject and cancel this order? Any payment will be refunded.">Reject order</button></div></form><?php endif; ?></section><?php endif; ?>
<?php if(!empty($order['verify_outcome'])&&$order['status']!=='awaiting_verification'): ?><section class="panel"><h2>Verification</h2><p class="help-text">Outcome: <strong><?= $e($order['verify_outcome']) ?></strong><?= !empty($order['verify_note'])?' — '.$e($order['verify_note']):'' ?><?= !empty($order['verified_at'])?' ('.gmdate('Y-m-d H:i',(int)$order['verified_at']).' UTC)':'' ?>.</p></section><?php endif; ?>
<section class="panel"><h2>Delivery address</h2><address><?php foreach(['recipient','phone','line1','line2','city','state','postal_code','country_code'] as $fieldName): ?><?php if(!empty($order['address'][$fieldName])): ?><span><?= $e($order['address'][$fieldName]) ?></span><?php endif; ?><?php endforeach; ?></address><h3>Order timeline</h3><ol class="timeline"><?php foreach($order['history'] as $entry): ?><li><strong><?= $e($entry['to_status']) ?></strong><span><?= $e($entry['reason']) ?></span><small><?= gmdate('Y-m-d H:i',(int)$entry['created_at']) ?> UTC</small></li><?php endforeach; ?></ol></section></div>
<?php $targets=OrderStates::targets($order['status']); ?>
<section class="panel"><div class="panel-heading"><div><h2>Update fulfillment</h2><p>Only valid next statuses are available. Cancellation restores consumed stock once.</p></div><span class="pill">Revision <?= $e($order['revision']) ?></span></div><?php if($can('admin.orders.edit')&&$targets): ?><form method="post" action="<?= $u('admin/order') ?>" data-validate><?php $hidden(['csrf'=>$csrf,'id'=>$order['id'],'revision'=>$values['revision']??$order['revision'],'operation_key'=>$values['operation_key']??$key()]); ?><div class="form-grid"><label class="field"><span>Next status</span><select name="target" required><option value="">Select next status</option><?php foreach($targets as $target): ?><option value="<?= $e($target) ?>" <?= ($values['target']??'')===$target?'selected':'' ?>><?= $e($target) ?></option><?php endforeach; ?></select></label><?php $field('reason','Reason / fulfillment note',$values['reason']??'','text','required maxlength="190"'); ?></div><div class="form-actions"><button class="button">Update order</button><a class="button secondary" href="<?= $u('admin/orders') ?>">Back to orders</a></div></form><?php else: ?><p class="notice"><?= $targets?'Your account has read-only order access.':'This order has no further fulfillment transitions.' ?></p><?php endif; ?></section>
<?php require __DIR__.'/footer.php'; ?>
